import{_ as t,o as n,c as a,ag as s}from"./chunks/framework.BpFM782D.js";const h=JSON.parse('{"title":"cicd-patterns","description":"","frontmatter":{},"headers":[],"relativePath":"en/skills/cicd-patterns.md","filePath":"en/skills/cicd-patterns.md"}'),i={name:"en/skills/cicd-patterns.md"};function o(r,e,l,c,d,p){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="cicd-patterns" tabindex="-1">cicd-patterns <a class="header-anchor" href="#cicd-patterns" aria-label="Permalink to &quot;cicd-patterns&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Name</td><td>cicd-patterns</td></tr><tr><td>Description</td><td>Verified CI/CD pitfall solutions database (not generic troubleshooting). Covers Docker ARG/ENV confusion, .dockerignore glob recursive false-kills, container EACCES permissions, Next.js standalone HOSTNAME binding, CI env var test pollution, Runner tag routing, cross-repo static site deployment, and more.</td></tr><tr><td>Source Directory</td><td><code>skills/cicd-patterns/</code></td></tr></tbody></table><hr><h1 id="ci-cd-patterns-—-troubleshooting-skill" tabindex="-1">CI/CD Patterns — Troubleshooting Skill <a class="header-anchor" href="#ci-cd-patterns-—-troubleshooting-skill" aria-label="Permalink to &quot;CI/CD Patterns — Troubleshooting Skill&quot;">​</a></h1><p>6 universal CI/CD patterns extracted from real-world experience. These patterns are not tied to any specific framework or CI platform and apply to any project using Docker + CI/CD.</p><hr><h2 id="pattern-quick-reference" tabindex="-1">Pattern Quick Reference <a class="header-anchor" href="#pattern-quick-reference" aria-label="Permalink to &quot;Pattern Quick Reference&quot;">​</a></h2><p>Use your <strong>symptoms</strong> to quickly identify the likely pattern:</p><table tabindex="0"><thead><tr><th>#</th><th>Pattern</th><th>Typical Symptoms</th><th>Reference</th></tr></thead><tbody><tr><td>1</td><td>Build vs Runtime Confusion</td><td>Environment variables missing at runtime, API version incompatibility, container hostname issues</td><td><code>references/pattern-build-vs-runtime.md</code></td></tr><tr><td>2</td><td>Local vs CI Inconsistency</td><td>Works locally but fails in CI, extra errors in CI, different test results</td><td><code>references/pattern-local-vs-ci.md</code></td></tr><tr><td>3</td><td>Glob Behavior Differences</td><td>Files unexpectedly excluded, build succeeds but content disappears, ignore rules behave unexpectedly</td><td><code>references/pattern-glob-behaviors.md</code></td></tr><tr><td>4</td><td>Non-Root Container Permissions</td><td>EACCES permission errors, cache write failures, image optimization failures</td><td><code>references/pattern-container-permissions.md</code></td></tr><tr><td>5</td><td>Multi-Runner Routing</td><td>Job pending with no runner found, job running in wrong environment</td><td><code>references/pattern-runner-routing.md</code></td></tr><tr><td>6</td><td>Cross-Repo Static Site Deployment</td><td>Private repo cannot use Pages, deploy key setup, base path 404, missing <code>.nojekyll</code></td><td><code>references/pattern-cross-repo-deploy.md</code></td></tr></tbody></table><hr><h2 id="diagnostic-decision-tree" tabindex="-1">Diagnostic Decision Tree <a class="header-anchor" href="#diagnostic-decision-tree" aria-label="Permalink to &quot;Diagnostic Decision Tree&quot;">​</a></h2><p>When encountering CI/CD issues, investigate in the following order:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Which phase did the problem occur?</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ Build phase failure</span></span>
<span class="line"><span>│  ├─ Docker build failed → Check Pattern 1 (version compatibility)</span></span>
<span class="line"><span>│  ├─ Lint / Test failed → Check Pattern 2 (environment differences)</span></span>
<span class="line"><span>│  └─ Build succeeded but artifacts incomplete → Check Pattern 3 (Glob exclusion)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ Runtime phase anomaly</span></span>
<span class="line"><span>│  ├─ Missing environment variables → Check Pattern 1 (ARG vs ENV)</span></span>
<span class="line"><span>│  ├─ Permission error (EACCES) → Check Pattern 4 (non-root permissions)</span></span>
<span class="line"><span>│  └─ Healthcheck failed → Check Pattern 1 (hostname binding)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ Job scheduling issues</span></span>
<span class="line"><span>│  └─ Job pending / routing error → Check Pattern 5 (Runner routing)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ Deploy / Pages issues</span></span>
<span class="line"><span>│  ├─ Private repo cannot enable Pages → Check Pattern 6 (Cross-Repo deployment)</span></span>
<span class="line"><span>│  ├─ Deployment succeeded but page is blank or 404 → Check Pattern 6 (base path / .nojekyll)</span></span>
<span class="line"><span>│  └─ startup_failure → Check Pattern 6 (billing / permissions / syntax)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└─ Local and CI results differ</span></span>
<span class="line"><span>   └─ Go directly to Pattern 2 (environment isolation)</span></span></code></pre></div><hr><h2 id="prevention-checklist" tabindex="-1">Prevention Checklist <a class="header-anchor" href="#prevention-checklist" aria-label="Permalink to &quot;Prevention Checklist&quot;">​</a></h2><p>Before setting up or modifying CI/CD configuration, verify each item:</p><h3 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><ul><li>[ ] CI Docker image version &gt;= minimum API requirement of the host Docker daemon</li><li>[ ] In Dockerfile, use <code>ARG</code> for build-time values and <code>ENV</code> for runtime values</li><li>[ ] Non-root user has write access to cache/log/upload directories</li><li>[ ] Container service binds to <code>0.0.0.0</code> (not localhost or container ID)</li><li>[ ] <code>.dockerignore</code> exclusion rules do not accidentally remove required files (especially recursive matching of <code>*.ext</code>)</li></ul><h3 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h3><ul><li>[ ] CI Protected Variables do not pollute test jobs</li><li>[ ] Tests control their own environment variables, not relying on external state</li><li>[ ] <code>#</code> after <code>=</code> in <code>.env</code> files is not treated as a comment (must be on its own line)</li><li>[ ] <code>--env-file</code> (CLI) and <code>env_file</code> (compose directive) serve different purposes — confirm both are configured</li></ul><h3 id="lint-test" tabindex="-1">Lint / Test <a class="header-anchor" href="#lint-test" aria-label="Permalink to &quot;Lint / Test&quot;">​</a></h3><ul><li>[ ] Run <code>lint</code> + <code>test</code> locally before committing</li><li>[ ] Handle lint compatibility for third-party components (e.g., shadcn/ui) immediately after installation</li><li>[ ] Regular expressions have no superlinear backtracking risk (<code>(.+)</code> → <code>([^\\n]+)</code>)</li></ul><h3 id="runner" tabindex="-1">Runner <a class="header-anchor" href="#runner" aria-label="Permalink to &quot;Runner&quot;">​</a></h3><ul><li>[ ] Each job&#39;s tags precisely match the target Runner</li><li>[ ] Jobs requiring a Node environment and jobs requiring a Docker socket use different tags</li></ul><h3 id="cross-repo-deployment" tabindex="-1">Cross-Repo Deployment <a class="header-anchor" href="#cross-repo-deployment" aria-label="Permalink to &quot;Cross-Repo Deployment&quot;">​</a></h3><ul><li>[ ] Deploy key uses Ed25519 with write access enabled on the target repo</li><li>[ ] Private key stored as an Actions secret in the source repo with a name matching the workflow</li><li>[ ] Static site <code>base</code> path corresponds to the target repo name (or set to <code>/</code> for custom domains)</li><li>[ ] <code>publish_dir</code> points to the correct build output directory</li><li>[ ] Target repo Pages source set to <code>gh-pages</code> branch</li></ul><hr><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><ol><li><strong>When a problem occurs</strong>: Check the quick reference first and identify the likely pattern based on symptoms</li><li><strong>Read the corresponding reference</strong>: Each pattern has concrete examples and general solutions</li><li><strong>Apply the prevention checklist</strong>: Use the checklist after fixing to ensure the issue won&#39;t recur</li><li><strong>Document new cases</strong>: If it&#39;s a new pattern, consider contributing it to <code>docs/cicd-troubleshooting.md</code></li></ol><hr><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li>Patterns 1–5 extracted from <code>frontstage-web/docs/cicd-troubleshooting.md</code> (2026-03-09), covering 8 real-world issues in a GitLab CI + Docker + Next.js standalone architecture.</li><li>Pattern 6 extracted from the <code>team-claude-config</code> VitePress documentation site cross-repo deployment (2026-03-21), covering the complete GitHub Actions + Deploy Key + GitHub Pages workflow.</li><li>All patterns have been generalized and are not tied to any specific framework.</li></ul>`,32)])])}const m=t(i,[["render",o]]);export{h as __pageData,m as default};
